'use strict';

// MODULES //

var gunzipSync = require( 'node:zlib' ).gunzipSync;
var assertCanonicalGzip = require( '@data-apis/record/assert-canonical-gzip' );
var filenameTimestamp = require( '@data-apis/record/filename-timestamp' );
var originSummary = require( '@data-apis/record/origin-summary' );
var parsePath = require( '@data-apis/record/parse-path' );
var sourceFingerprint = require( '@data-apis/registry/source-fingerprint' );
var normalizeTimestamp = require( '@data-apis/report/normalize-timestamp' );
var validateReport = require( '@data-apis/publish/validate-report' );


// VARIABLES //

var SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
var SHA256 = /^[0-9a-f]{64}$/;
var SHA256_PREFIXED = /^sha256:[0-9a-f]{64}$/;


// FUNCTIONS //

/**
* Asserts that a value is a plain JSON object.
*
* @private
* @param {*} value - value
* @param {string} field - field name
*/
function requireObject( value, field ) {
	if ( !value || typeof value !== 'object' || Array.isArray( value ) ) {
		throw new Error( field + ' must be an object' );
	}
}

/**
* Asserts that an object contains required fields and no unknown fields.
*
* @private
* @param {Object} value - object
* @param {Array<string>} required - required fields
* @param {Array<string>} optional - optional fields
* @param {string} name - object name
*/
function requireFields( value, required, optional, name ) {
	var keys = Object.keys( value );
	var allowed = new Set( required.concat( optional || [] ) );

	required.forEach( function requireField( field ) {
		if ( !Object.hasOwn( value, field ) ) {
			throw new Error( name + ' is missing ' + field );
		}
	} );
	if ( keys.some( function unknown( field ) { return !allowed.has( field ); } ) ) {
		throw new Error( name + ' contains an unknown field' );
	}
}

/**
* Asserts a bounded nonempty string.
*
* @private
* @param {*} value - value
* @param {string} field - field name
* @param {number} [maximum=512] - maximum length
*/
function requireString( value, field, maximum ) {
	maximum = maximum || 512;
	if ( typeof value !== 'string' || value.length === 0 || value.length > maximum ) {
		throw new Error( field + ' must be a bounded string' );
	}
}

/**
* Validates stored payload provenance.
*
* @private
* @param {Object} payload - payload provenance
*/
function validatePayload( payload ) {
	requireObject( payload, 'origin.payload' );
	requireFields( payload, ['format'], ['member'], 'origin.payload' );
	if ( !['json', 'zip'].includes( payload.format ) || ( payload.format === 'zip' ) !== Object.hasOwn( payload, 'member' ) ) {
		throw new Error( 'Stored payload format/member agreement is invalid' );
	}
	if ( payload.member !== undefined ) {
		requireString( payload.member, 'origin.payload.member' );
	}
}

/**
* Validates provider-neutral origin and registered endpoint agreement.
*
* @private
* @param {Object} origin - origin provenance
* @param {Object} source - registered source
*/
function validateOrigin( origin, source ) {
	requireObject( origin, 'harvest.origin' );
	if ( source.type === 'url' ) {
		requireFields( origin, ['type', 'endpoint', 'payload'], ['response'], 'harvest.origin' );
		if ( origin.type !== 'url' || origin.endpoint !== source.url ) {
			throw new Error( 'Stored URL origin differs from the registry' );
		}
		if ( origin.response !== undefined ) {
			requireObject( origin.response, 'origin.response' );
			requireFields( origin.response, [], ['etag', 'last_modified'], 'origin.response' );
			Object.values( origin.response ).forEach( function validateHeader( value ) {
				requireString( value, 'origin.response value' );
			} );
		}
		validatePayload( origin.payload );
		return;
	}
	requireFields( origin, ['type', 'provider', 'project', 'ref', 'run', 'artifact', 'payload'], ['provider_details'], 'harvest.origin' );
	if ( origin.type !== 'ci_artifact' || origin.provider !== source.provider ) {
		throw new Error( 'Stored CI origin differs from the registry' );
	}
	requireObject( origin.project, 'origin.project' );
	requireFields( origin.project, ['id', 'locator'], [], 'origin.project' );
	requireString( origin.project.id, 'origin.project.id' );
	requireString( origin.project.locator, 'origin.project.locator' );
	if ( origin.project.locator.toLowerCase() !== source.project.toLowerCase() ) {
		throw new Error( 'Stored CI project differs from the registry' );
	}
	requireObject( origin.ref, 'origin.ref' );
	requireFields( origin.ref, ['kind', 'name'], [], 'origin.ref' );
	requireString( origin.ref.kind, 'origin.ref.kind' );
	requireString( origin.ref.name, 'origin.ref.name' );
	if ( origin.ref.kind !== source.ref.kind || origin.ref.name !== source.ref.name ) {
		throw new Error( 'Stored CI ref differs from the registry' );
	}
	requireObject( origin.run, 'origin.run' );
	requireFields( origin.run, ['id'], ['revision'], 'origin.run' );
	requireString( origin.run.id, 'origin.run.id' );
	if ( origin.run.revision !== undefined ) {
		requireString( origin.run.revision, 'origin.run.revision' );
	}
	requireObject( origin.artifact, 'origin.artifact' );
	requireFields( origin.artifact, ['name'], ['id'], 'origin.artifact' );
	requireString( origin.artifact.name, 'origin.artifact.name' );
	if ( origin.artifact.id !== undefined ) {
		requireString( origin.artifact.id, 'origin.artifact.id' );
	}
	if ( origin.artifact.name !== source.selector.artifact ) {
		throw new Error( 'Stored artifact differs from the registry' );
	}
	validatePayload( origin.payload );
	if ( origin.provider_details !== undefined ) {
		if ( origin.provider !== 'github' ) {
			throw new Error( 'Stored provider details have no registered schema branch' );
		}
		requireObject( origin.provider_details, 'origin.provider_details' );
		requireFields( origin.provider_details, [], ['workflow', 'run_attempt', 'artifact_created_at', 'artifact_digest'], 'origin.provider_details' );
		if ( origin.provider_details.workflow !== undefined ) {
			requireString( origin.provider_details.workflow, 'origin.provider_details.workflow' );
			if ( origin.provider_details.workflow !== source.selector.workflow ) {
				throw new Error( 'Stored workflow differs from the registry' );
			}
		}
		if ( origin.provider_details.run_attempt !== undefined && ( !Number.isSafeInteger( origin.provider_details.run_attempt ) || origin.provider_details.run_attempt < 1 ) ) {
			throw new Error( 'Stored run attempt is invalid' );
		}
		if ( origin.provider_details.artifact_digest !== undefined && !SHA256_PREFIXED.test( origin.provider_details.artifact_digest ) ) {
			throw new Error( 'Stored artifact digest is invalid' );
		}
		if ( origin.provider_details.artifact_created_at !== undefined ) {
			requireString( origin.provider_details.artifact_created_at, 'origin.provider_details.artifact_created_at' );
			if ( normalizeTimestamp( origin.provider_details.artifact_created_at ) !== origin.provider_details.artifact_created_at ) {
				throw new Error( 'Stored artifact creation timestamp is not normalized' );
			}
		}
	}
}


// MAIN //

/**
* Validates a stored record and derives its exact index row without third-party code.
*
* @param {Buffer} bytes - gzip bytes
* @param {string} recordPath - path relative to data
* @param {Object} library - registered library
* @param {Object} source - registered source
* @returns {Object} envelope and derived index row
*/
function validateEnvelope( bytes, recordPath, library, source ) {
	var envelope;
	var harvest;
	var report;
	var parsed = parsePath( recordPath );

	try {
		envelope = JSON.parse( new TextDecoder( 'utf-8', { 'fatal': true } ).decode( gunzipSync( bytes, {
			'maxOutputLength': 55 * 1024 * 1024
		} ) ) );
	} catch ( error ) {
		throw new Error( 'Unable to decode stored record ' + recordPath + ': ' + error.message, { 'cause': error } );
	}
	requireObject( envelope, 'stored record' );
	requireFields( envelope, ['schema', 'harvest', 'report'], [], 'stored record' );
	if ( envelope.schema !== 'stored-record-v1' ) {
		throw new Error( 'Unsupported stored record schema' );
	}
	requireObject( envelope.harvest, 'harvest' );
	requireFields( envelope.harvest, ['library_id', 'source_id', 'source_fingerprint', 'series_schema', 'series_key', 'retrieved_at', 'report_sha256', 'origin'], [], 'harvest' );
	harvest = envelope.harvest;
	if ( !SLUG.test( harvest.library_id ) || !SLUG.test( harvest.source_id ) || !SHA256_PREFIXED.test( harvest.source_fingerprint ) || !SHA256_PREFIXED.test( harvest.series_key ) || !SHA256.test( harvest.report_sha256 ) ) {
		throw new Error( 'Stored harvest identifiers are malformed' );
	}
	if ( harvest.library_id !== library.id || harvest.source_id !== source.id || parsed.libraryId !== library.id || parsed.sourceId !== source.id ) {
		throw new Error( 'Stored record IDs do not agree with its path' );
	}
	if ( harvest.source_fingerprint !== sourceFingerprint( source ) ) {
		throw new Error( 'Stored source fingerprint differs from the registry' );
	}
	report = validateReport( envelope.report, library.report_name || library.id );
	if ( harvest.series_schema !== report.seriesSchema || harvest.series_key !== report.seriesKey || harvest.report_sha256 !== report.reportSha256 || parsed.reportSha256 !== report.reportSha256 || parsed.filenameTimestamp !== filenameTimestamp( report.timestamp ) ) {
		throw new Error( 'Stored record derivation does not agree with path/report' );
	}
	if ( typeof harvest.retrieved_at !== 'string' || normalizeTimestamp( harvest.retrieved_at ) !== harvest.retrieved_at ) {
		throw new Error( 'Stored retrieval timestamp is not normalized' );
	}
	validateOrigin( harvest.origin, source );
	assertCanonicalGzip( bytes, envelope );
	return {
		'envelope': envelope,
		'row': {
			'library_id': harvest.library_id,
			'source_id': harvest.source_id,
			'source_fingerprint': harvest.source_fingerprint,
			'series_schema': harvest.series_schema,
			'series_key': harvest.series_key,
			'origin': originSummary( harvest.origin ),
			'series': report.series,
			'timestamp': report.timestamp,
			'path': recordPath,
			'report_sha256': report.reportSha256,
			'version': envelope.report.version,
			'api_version': envelope.report.api_version,
			'python': envelope.report.python,
			'platform': structuredClone( envelope.report.platform ),
			'test_suite': envelope.report.test_suite,
			'summary': structuredClone( envelope.report.data.summary )
		}
	};
}


// EXPORTS //

module.exports = validateEnvelope;
